package dev.riichicraft.rules;

import dev.riichicraft.persistence.TableArchiveStore;
import java.io.IOException;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.Arrays;
import java.util.HexFormat;
import java.util.List;
import java.util.Properties;
import java.util.Set;
import java.util.UUID;
import static dev.riichicraft.rules.DiscardResponseWindow.Simple;

/** Fixed old-writer bytes, not fixtures regenerated by the current implementation during tests. */
public final class LegacyArchiveTests {
    private static final String ROOT = "/dev/riichicraft/rules/legacy/v0.0.16/";
    private static final String WRITER_SHA = "2dc248499ec8e60851dc4d73b0e91c63e9db8657f6f3ceef596b1f0e1e03d7a5";
    private static int assertions;

    public static void main(String[] args) {
        assertions = 0;
        try {
            checkFrozenManifestAndEveryArchive();
            partialFourPlayerDeclaration();
            partialNorthRobbery();
            savedVotesAndFinalAccounts();
            historicallyAcceptedNorthExhaustionCanContinue();
        } catch (Exception failure) {
            throw new AssertionError("Historical v0.0.16 archive compatibility failed", failure);
        }
        System.out.println("PASS frozen v0.0.16 archives: " + assertions + " assertions; 14 historical files");
    }

    private static void checkFrozenManifestAndEveryArchive() throws Exception {
        var manifest = new Properties();
        try (var input = new InputStreamReader(resource("manifest.properties"), StandardCharsets.UTF_8)) { manifest.load(input); }
        check(manifest.getProperty("format.version").equals("1") && manifest.getProperty("writer.jar.sha256").equals(WRITER_SHA),
                "The manifest identifies the exact historical production writer");
        check(manifest.getProperty("source.ref").equals("51e06b0ff9b9f527938f004dbeb83cb9c4a55ea0"), "Historical source ref is frozen");
        var names = List.of(manifest.getProperty("fixture.names").split(","));
        check(names.size() == 14 && Set.copyOf(names).equals(Set.of("four-active", "four-partial-riichi", "four-scored-win",
                "four-match-active-east", "four-match-intermission-south", "four-match-final-south", "three-north-active",
                "three-scored-win", "three-partial-north", "three-match-active-south", "three-match-intermission-east",
                "three-match-final-east", "three-riichi-north-exhausted", "world-tables-v2")), "All expected historical cases are present exactly once");
        for (String name : names) {
            byte[] original = bytes(name);
            String expectedHash = manifest.getProperty("fixture." + name + ".sha256");
            check(HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(original)).equals(expectedHash), "Frozen bytes match their original digest: " + name);
            String summary;
            byte[] encoded;
            switch (manifest.getProperty("fixture." + name + ".kind")) {
                case "FOUR_ROUND" -> {
                    var round = GameArchiveCodec.decodeRound(original);
                    round.assertConservation();
                    summary = LegacyArchiveSummary.four(round); encoded = GameArchiveCodec.encodeRound(round);
                }
                case "FOUR_MATCH" -> {
                    var match = fourMatch(name);
                    summary = LegacyArchiveSummary.four(match); encoded = GameArchiveCodec.encodeMatch(match);
                }
                case "THREE_ROUND" -> {
                    var round = ThreePlayerArchiveCodec.decodeRound(original);
                    round.assertConservation();
                    summary = LegacyArchiveSummary.three(round); encoded = ThreePlayerArchiveCodec.encodeRound(round);
                }
                case "THREE_MATCH" -> {
                    var match = threeMatch(name);
                    summary = LegacyArchiveSummary.three(match); encoded = ThreePlayerArchiveCodec.encodeMatch(match);
                }
                case "WORLD_TABLES" -> {
                    var tables = TableArchiveStore.decode(original);
                    summary = LegacyArchiveSummary.world(tables); encoded = TableArchiveStore.encode(tables);
                    check(tables.size() == 2 && tables.getFirst().chairSides().equals(List.of(2, 3, 0, 1))
                            && tables.getLast().chairSides().equals(List.of(1, 2, 0)), "Historical v2 container preserves both rotated physical rosters");
                }
                default -> throw new AssertionError("Unknown historical archive kind: " + name);
            }
            check(Arrays.equals(original, encoded), "Current reader re-encodes the exact historical bytes: " + name);
            check(summary.equals(manifest.getProperty("fixture." + name + ".summary")), "Current semantics match the explicit old-writer summary: " + name);
        }
    }

    private static void partialFourPlayerDeclaration() throws IOException {
        var round = GameArchiveCodec.decodeRound(bytes("four-partial-riichi"));
        var seats = round.view(null).seats();
        var window = round.view(null).opportunity().orElseThrow().id();
        check(round.serverState().riichi().getFirst().phase() == RiichiState.Phase.PENDING
                        && round.view(null).deposits() == 3 && round.serverState().ledger().points().equals(List.of(24000, 24000, 24000, 25000)),
                "Loading does not charge the pending riichi or pay the saved ron early");
        check(round.view(seats.get(3).playerId()).responses().isEmpty()
                        && round.respond(seats.get(2).playerId(), window, Simple.RON) == FourPlayerRound.Status.ALREADY_RESPONDED,
                "The historical pass and historical ron are already answered after restoration");
        check(round.respond(seats.get(1).playerId(), window, Simple.RON) == FourPlayerRound.Status.ACCEPTED
                        && round.view(null).end().orElseThrow().winners().equals(List.of(1, 2)), "Only the remaining winner completes the saved multi-ron window");
        check(round.serverState().riichi().getFirst().phase() == RiichiState.Phase.UNDECLARED
                        && round.view(null).end().orElseThrow().transfers().stream().filter(t -> t.kind() == RoundLedger.Kind.DEPOSIT).mapToInt(RoundLedger.Transfer::points).sum() == 3000,
                "The interrupted declaration is canceled and only the three old sticks are paid once");
        round.assertConservation();
    }

    private static void partialNorthRobbery() throws IOException {
        var round = ThreePlayerArchiveCodec.decodeRound(bytes("three-partial-north"));
        var seats = round.view(null).seats(); var window = round.view(null).opportunity().orElseThrow().id();
        check(round.view(null).phase() == ThreePlayerRound.Phase.NORTH_RESPONSES
                        && round.serverState().wall().replacementDraws() == 0 && round.serverState().norths().getFirst().isEmpty(),
                "The saved north proposal remains unestablished without a replacement draw");
        check(round.respond(seats.get(1).playerId(), window, Simple.RON) == ThreePlayerRound.Status.ALREADY_RESPONDED
                        && round.respond(seats.get(2).playerId(), window, Simple.RON) == ThreePlayerRound.Status.ACCEPTED,
                "The collected north-robbery ron is retained and the other claimant can finish it");
        check(round.view(null).end().orElseThrow().winners().equals(List.of(1, 2))
                        && round.serverState().ledger().points().equals(List.of(29600, 37800, 37600))
                        && round.serverState().wall().replacementDraws() == 0,
                "Restored double ron pays the original accounts without establishing the robbed north");
        round.assertConservation();
    }

    private static void savedVotesAndFinalAccounts() throws IOException {
        var four = fourMatch("four-match-intermission-south");
        check(four.view(null).confirmations().equals(List.of(true, true, false, true))
                        && four.serverState().ledger().points().equals(List.of(96000, 0, 0, 0)) && four.view(null).round().deposits() == 4,
                "Historical intermission keeps its exact three votes, carried scores and funded pool");
        check(four.confirmNext(four.view(null).round().seats().get(1).playerId(), four.view(null).continueId()) == FourPlayerRound.Status.ALREADY_RESPONDED,
                "An already collected historical continue vote cannot count twice");
        var three = threeMatch("three-match-intermission-east");
        check(three.view(null).confirmations().equals(List.of(true, false, true)), "Sanma retains its saved two-vote quorum fragment");
        check(three.confirmNext(three.view(null).round().seats().getFirst().playerId(), three.view(null).continueId()) == ThreePlayerRound.Status.ALREADY_RESPONDED,
                "A historical sanma vote is also idempotent");
        var finalFour = fourMatch("four-match-final-south");
        check(finalFour.view(null).phase() == FourPlayerMatch.Phase.MATCH_RESULT
                        && finalFour.view(null).result().orElseThrow().depositPoints() == 4000
                        && finalFour.view(null).result().orElseThrow().standings().stream().map(MatchRules.Standing::points).toList().equals(List.of(103000, -1000, -1000, -1000)),
                "The final historical pool is already awarded exactly once to the saved standings");
        check(finalFour.confirmNext(finalFour.view(null).round().seats().getFirst().playerId(), finalFour.view(null).continueId()) == FourPlayerRound.Status.WRONG_PHASE,
                "A historical final result cannot construct another round");
        check(threeMatch("three-match-final-east").view(null).phase() == ThreePlayerMatch.Phase.MATCH_RESULT,
                "Historical sanma final standings restore without a future factory");
    }

    private static void historicallyAcceptedNorthExhaustionCanContinue() throws IOException {
        var round = ThreePlayerArchiveCodec.decodeRound(bytes("three-riichi-north-exhausted"));
        UUID east = round.view(null).seats().getFirst().playerId();
        var own = round.view(east);
        check(round.serverState().norths().getFirst().size() == 3 && round.serverState().riichi().getFirst().establishedRiichi() == WinContext.Riichi.DOUBLE_RIICHI
                        && own.turnOptions().discards().equals(Set.of(own.ownDraw().orElseThrow())) && own.turnOptions().kans().isEmpty(),
                "An old accepted state whose own view crashed now offers its exact legal riichi discard");
        check(round.discard(east, own.command(), own.ownDraw().orElseThrow(), false) == ThreePlayerRound.Status.ACCEPTED,
                "The historical three-north state can actually continue with its conserved replacement tile");
        for (int step = 0; round.view(null).phase() != ThreePlayerRound.Phase.FINISHED; step++) {
            check(step < 600, "The historical suffix reaches settlement within the finite wall budget");
            var view = round.view(null);
            if (view.opportunity().isPresent()) {
                for (var seat : view.seats()) {
                    var offered = round.view(seat.playerId());
                    if (!offered.responses().isEmpty()) check(round.respond(seat.playerId(), offered.opportunity().orElseThrow().id(), Simple.PASS) == ThreePlayerRound.Status.ACCEPTED,
                            "Remaining players can answer each restored/continued opportunity");
                }
            } else {
                UUID actor = view.seats().get(view.actorSeat()).playerId(); var current = round.view(actor);
                check(round.discard(actor, current.command(), current.ownDraw().orElseThrow(), false) == ThreePlayerRound.Status.ACCEPTED,
                        "Actual players complete the historical suffix through legal tsumogiri");
            }
            round.assertConservation();
        }
        check(round.view(null).end().orElseThrow().kind() == ThreePlayerRound.EndKind.EXHAUSTIVE
                        && !round.view(null).end().orElseThrow().tenpai().contains(0),
                "The historical north-exhausted riichi hand is correctly not tenpai at exhaustive draw");
    }

    private static FourPlayerMatch fourMatch(String name) throws IOException {
        return GameArchiveCodec.decodeMatch(bytes(name), setup -> { throw new AssertionError("Restoration must never invoke the future four-player factory"); });
    }
    private static ThreePlayerMatch threeMatch(String name) throws IOException {
        return ThreePlayerArchiveCodec.decodeMatch(bytes(name), setup -> { throw new AssertionError("Restoration must never invoke the future three-player factory"); });
    }
    private static byte[] bytes(String name) throws IOException {
        try (var input = resource(name + ".bin")) { return input.readAllBytes(); }
    }
    private static java.io.InputStream resource(String name) {
        var stream = LegacyArchiveTests.class.getResourceAsStream(ROOT + name);
        if (stream == null) throw new AssertionError("Missing frozen test resource " + name);
        return stream;
    }
    private static void check(boolean good, String message) {
        assertions++;
        if (!good) throw new AssertionError(message);
    }
}
